package com.bank.labelmig.dto;

// Holds the deletions and insertions needed for the transform.
public class TransformCost {
    private final int deletions;
    private final int insertions;

    public TransformCost(int deletions, int insertions) {
        this.deletions = deletions;
        this.insertions = insertions;
    }

    public int getDeletions() { return deletions; }
    public int getInsertions() { return insertions; }
}
