package com.bank.labelmig.service;

import com.bank.labelmig.dto.TransformCost;
import java.util.logging.Logger;

// Deletions and insertions derived from the longest common subsequence.
public class LabelMigrationService {
    private static final Logger log = Logger.getLogger(LabelMigrationService.class.getName());

    public TransformCost transformCost(String oldLabel, String newLabel) {
        int m = oldLabel.length(), n = newLabel.length();
        int[][] dp = new int[m + 1][n + 1];         // longest common subsequence table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (oldLabel.charAt(i - 1) == newLabel.charAt(j - 1))
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                else
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        int lcs = dp[m][n];
        int deletions = m - lcs;                    // old chars not in shared core
        int insertions = n - lcs;                   // new chars not in shared core
        log.info(() -> "Transform " + oldLabel + " to " + newLabel
                + ": deletions=" + deletions + " insertions=" + insertions);
        return new TransformCost(deletions, insertions);
    }
}
