package com.bank.labelmig;

import com.bank.labelmig.dto.TransformCost;
import com.bank.labelmig.service.LabelMigrationService;
import java.util.logging.Logger;

public class LabelMigrationApplication {
    private static final Logger log = Logger.getLogger(LabelMigrationApplication.class.getName());

    public static void main(String[] args) {
        LabelMigrationService service = new LabelMigrationService();
        TransformCost cost = service.transformCost("SAVINGS", "SAVING");
        log.info("Deletions " + cost.getDeletions() + ", insertions " + cost.getInsertions());
    }
}
